package service_test
import("context";"testing";"github.com/google/uuid";"github.com/SupanatSMOST/tennis-tracker/backend/internal/cvresult";"github.com/SupanatSMOST/tennis-tracker/backend/internal/service")
func TestCVImportEligibilityAndDeterministicIDs(t *testing.T){match:=uuid.New();zone:="out_behind";events:=[]cvresult.Event{{EventID:"accept",EventType:"bounce",TimestampMS:10,Zone:&zone,ReviewStatus:"accepted"},{EventID:"correct",EventType:"bounce",TimestampMS:20,Zone:&zone,ReviewStatus:"corrected"},{EventID:"pending",EventType:"bounce",TimestampMS:30,Zone:&zone,ReviewStatus:"needs_review"},{EventID:"unresolved",EventType:"bounce",TimestampMS:40,Zone:&zone,ReviewStatus:"unresolved"},{EventID:"reject",EventType:"bounce",TimestampMS:50,Zone:&zone,ReviewStatus:"rejected"}};r:=cvresult.Result{SchemaVersion:"1.0",MatchID:match.String(),CalibrationID:"cal",Video:cvresult.Video{DurationMS:1000,Width:100,Height:100,FPS:30},Model:cvresult.Model{Name:"m",Version:"1",Runtime:"test"},Events:events};first:=service.CVRecordIDsForTest(match,r);second:=service.CVRecordIDsForTest(match,r);if len(first)!=2||len(second)!=2{t.Fatalf("eligible IDs: got %d and %d; want 2",len(first),len(second))};for i:=range first{if first[i]!=second[i]{t.Fatalf("retry ID mismatch: %s != %s",first[i],second[i])}};if first[0]==first[1]{t.Fatal("distinct event IDs collided")}}
func TestCVImportValidationDoesNotCallStore(t *testing.T){svc:=service.NewGameplayService(nil);match:=uuid.New();r:=cvresult.Result{SchemaVersion:"1.0",MatchID:uuid.NewString()};if _,err:=svc.ImportAcceptedCV(context.Background(),match,uuid.New(),r);err==nil{t.Fatal("wanted mismatch error")}}
